_EVENT = "auto_escalate"
_NULL_DATE = "00000000"


def _parse_legacy_date(value: object) -> date:
    """Parse a non-null Meridian YYYYMMDD date."""
    text = str(value)
    if len(text) != 8 or not text.isdigit():
        raise ValueError(f"invalid legacy date: {text!r}")
    return date(int(text[:4]), int(text[4:6]), int(text[6:8]))


def _datediff(d1: object, d2: object) -> int:
    """Return whole calendar days d1 - d2 using Meridian null semantics."""
    if d1 in ("", None, _NULL_DATE) or d2 in ("", None, _NULL_DATE):
        return 0
    return (_parse_legacy_date(d1) - _parse_legacy_date(d2)).days


