    """Return auto-escalation events in ascending CASE_ID order."""
    events: list[dict] = []
    emitted_case_ids: set[str] = set()

    ordered_cases = sorted(cases, key=lambda case: str(case["CASE_ID"]))

    for case in ordered_cases:
        if case.get("DEL_FLG", "") == "Y":
            continue

        case_id = str(case["CASE_ID"])
        if case_id in emitted_case_ids:
            continue

        status = case.get("STAT_CD", "")
        open_date = case.get("OPEN_DT", "")
        age = _datediff(today, open_date)

        overdue = (
            status == "N" and age >= 2
        ) or (
            status == "A"
            and case.get("ESC_FLG", "") != "Y"
            and age >= 7
        )

        if overdue:
            events.append(
                {
                    "workflow": _WORKFLOW,
                    "entity_id": case_id,
                    "event": _EVENT,
                }
            )
            emitted_case_ids.add(case_id)

    return events
